transforms.code:
if value is None:
	# Priority: Comm Loss (Bad quality) wins over Fault/other Status enum
	# Bad quality means PLC bits cannot be trusted.
	tag_path = ''
	try:
		tag_path = self.view.params.tagPath or ''
	except:
		pass
	if str(tag_path).strip() == '':
		return ''
	q = ''
	try:
		q = str(self.custom.quality or '')
	except:
		pass
	if q.startswith('Bad'):
		return 'Comm Loss'
	return ''
try:
	v = int(value)
except:
	return ''
# Prefer short display codes (Cooling = CLG, never RUN). Manual (4) not shown.
codes = {0: 'STOP', 1: 'CLG', 2: 'DFT', 3: 'FLT', 5: 'IDLE'}
states = self.custom.states
if states:
	try:
		for s in states:
			sv = s['value'] if hasattr(s, '__getitem__') else getattr(s, 'value', None)
			sl = s['label'] if hasattr(s, '__getitem__') else getattr(s, 'label', None)
			if sv is not None and int(sv) == v and sl not in (None, ''):
				key = str(sl).strip().upper()
				alias = {
					'OFF': 'STOP', 'STOP': 'STOP', 'STOPPED': 'STOP',
					'COOLING': 'CLG', 'CLG': 'CLG',
					'DEFROST': 'DFT', 'DFT': 'DFT',
					'FAULT': 'FLT', 'ALARM': 'FLT', 'FLT': 'FLT',
					'IDLE': 'IDLE', 'STANDBY': 'IDLE', 'IDL': 'IDLE',
					'RUN': 'RUN', 'RUNNING': 'RUN', 'ON': 'RUN',
					'COMM LOSS': 'Comm Loss', 'COMMLOSS': 'Comm Loss', 'COMM': 'Comm Loss'
				}
				# Manual enum bit — do not surface as status code
				if key in ('MANUAL', 'MAN') or v == 4:
					return ''
				# If tag metadata still says Run for cooling value, force CLG for value 1
				if v == 1:
					return 'CLG'
				return alias.get(key, key)
	except:
		pass
if v == 4:
	return ''
return codes.get(v, '')

